for path in Path("source/GoogleSans/").glob("*.ufo"):
    ufo = Font.open(path)
    otc = ufo.lib["public.openTypeCategories"]

    for name in ALL_GLYPHS:
        if name in otc:
            del otc[name]
    otc.update({k: "base" for k in BASES})
    otc.update({k: "mark" for k in MARKS})

    ufo.save()
